T("Adds automatic collection on top of Blizzard's own Auto Loot setting, which stays unchanged. Locked slots and confirmations stay manual.", "Agrega recolección automática además del ajuste Botín automático de Blizzard, que no cambia. Las casillas bloqueadas y las confirmaciones siguen siendo manuales.")
T("Adds guild rank, the hovered unit's target, item levels, the unit's current mount and item or spell details to Blizzard's main tooltip, and can show player names without titles. Your own item level and the one of the unit open in the Inspect window need no request. Item levels of other hovered players are a separate choice that sends inspect requests: at most one per hover, never while the Inspect window or another inspect is busy. Mounts are read once when a unit tooltip opens, out of combat; a change appears on the next hover. Place the fixed corner in MSUF Edit Mode; the cursor offsets apply to the cursor anchor.", "Añade a la descripción emergente principal de Blizzard el rango de hermandad, el objetivo de la unidad, niveles de objeto, la montura actual de la unidad y detalles de objetos o hechizos, y puede mostrar los nombres de jugador sin títulos. Tu propio nivel de objeto y el de la unidad abierta en la ventana de inspección no necesitan solicitud. Los niveles de objeto de otros jugadores señalados son una opción aparte que envía solicitudes de inspección: como mucho una por cada vez que señalas y nunca mientras la ventana de inspección u otra inspección estén ocupadas. Las monturas se leen una vez al abrir una descripción de unidad, fuera de combate; un cambio aparece la próxima vez que la señales. Coloca la esquina fija en el modo de edición de MSUF; los desplazamientos del cursor se aplican al anclaje al cursor.")
T("Adds the current-season Mythic+ score to the main tooltip of another player when Blizzard provides a public score. Unknown or restricted scores stay hidden.", "Agrega la puntuación Mítica+ de la temporada actual a la descripción emergente principal de otro jugador cuando Blizzard proporciona una puntuación pública. Las puntuaciones desconocidas o restringidas permanecen ocultas.")
T("Adjust the glass effect while keeping your colors and window coverage.", "Ajusta el efecto vidrio sin cambiar tus colores ni la cobertura de las ventanas.")
T("Adventure Guide", "Guía de Aventura")
T("After a completed Mythic+ run or successful raid encounter, show the public result values in a separate card. Choose which figures appear and how long the card stays open. The last result can be reopened here. Combat delays the card until it is safe to show.", "Muestra los resultados públicos en una tarjeta independiente tras completar Mítica+ o ganar un encuentro de banda. Elige qué cifras mostrar y cuánto tiempo permanece abierta. Puedes volver a abrir el último resultado aquí. El combate retrasa la tarjeta hasta que sea seguro mostrarla.")
