T("At a trainer, review the count and combined gold cost before buying. The button learns only abilities already available at confirmation, checks each step again, and stops when the trainer closes, combat starts or the list changes. Profession choices and rank steps stay manual.", "En el instructor, revisa la cantidad y el coste total en oro antes de comprar. El botón solo aprende las habilidades disponibles al confirmar, vuelve a comprobar cada paso y se detiene si se cierra el instructor, comienza el combate o cambia la lista. Las decisiones de profesión y los rangos siguen siendo manuales.")
