T("Blizzard Edit Mode owns position and layout. The optional glyph layer changes appearance while native clicks and notifications stay intact.", "El modo de edición de Blizzard controla la posición y el diseño. La capa opcional de glifos cambia el aspecto, mientras los clics y las notificaciones originales siguen intactos.")
T("Blizzard Edit Mode owns position and layout. The original button artwork, clicks and notifications stay intact.", "El modo de edición de Blizzard controla la posición y el diseño. Los gráficos originales de los botones, los clics y las notificaciones siguen intactos.")
