T("Blizzard keeps every original font size and style flag.", "Blizzard conserva cada tamaño de fuente y atributo de estilo originales.")
T("Blizzard keeps its text sizes and outlines.", "Blizzard conserva sus tamaños de texto y sus contornos.")
T("Blizzard keeps the button artwork, clicks, tooltips, enabled states and notifications. Optional glyph artwork is available in the detail controls. Visual changes apply outside combat only.", "Blizzard conserva los gráficos de los botones, los clics, las descripciones emergentes, los estados de activación y las notificaciones. Los glifos opcionales están disponibles en los controles detallados. Los cambios visuales solo se aplican fuera de combate.")
T("Blizzard layout captured", "Diseño de Blizzard capturado")
T("Blizzard layout imported", "Diseño de Blizzard importado")
T("Blizzard original", "Original de Blizzard")
T("Blizzard owns aggro flashes, progressive highlights and soft target icons. Optional colors tint Blizzard's existing threat textures; its health bar threat color stays under the role-color overlay. Soft target icons also need the nameplate icon switch enabled and a matching soft target in game.", "Blizzard controla los destellos de amenaza, los resaltados progresivos y los iconos de objetivo suave. Los colores opcionales tiñen las texturas de amenaza existentes; el color de amenaza de la barra de salud queda bajo la capa de color por función. Los iconos de objetivo suave también requieren activar los iconos de placas de nombre y un objetivo suave adecuado en el juego.")
T("Blizzard owns the aura icons and updates. Choose Keep Blizzard setting or Customize for each unit type. Buffs, debuffs and control effects can be selected and dragged separately in the preview. Aura size uses Blizzard's own setting.", "Blizzard controla los iconos de aura y sus actualizaciones. Elige Mantener ajuste de Blizzard o Personalizar para cada tipo de unidad. Los beneficios, los perjuicios y los efectos de control se pueden seleccionar y arrastrar por separado en la vista previa. El tamaño de aura usa el ajuste propio de Blizzard.")
T("Blizzard owns these elements. The rarity icon setting applies to all nameplates; raid target icons are hidden only on enemy plates. Castbar details control Blizzard's own castbar. The preview and live plates use the same switches.", "Blizzard controla estos elementos. El ajuste del icono de rareza se aplica a todas las placas de nombre; los iconos de objetivo de banda solo se ocultan en las placas enemigas. Los detalles de la barra de lanzamiento controlan la barra de lanzamiento propia de Blizzard. La vista previa y las placas en vivo usan los mismos interruptores.")
T("Blizzard personal auras", "Auras personales de Blizzard")
T("Blizzard plate size (health bar + elements)", "Tamaño de placa de Blizzard (barra de salud + elementos)")
T("Blizzard plate style", "Estilo de placa de Blizzard")
T("Blizzard raid target icon on enemy plates", "Icono de objetivo de banda de Blizzard en placas enemigas")
T("Blizzard setting", "Ajuste de Blizzard")
T("Blizzard shield", "Escudo de Blizzard")
T("Blizzard spell icon", "Icono de hechizo de Blizzard")
T("Blizzard supplies the castbar texture, colors, progress and interrupts. Customize its text and details here. Select and move each cast element in the preview; positions apply outside combat.", "Blizzard proporciona la textura, los colores, el progreso y las interrupciones de la barra de lanzamiento. Personaliza aquí su texto y sus detalles. Selecciona y mueve cada elemento del lanzamiento en la vista previa; las posiciones se aplican fuera de combate.")
T("Blizzard supplies the icons. The Suite keeps its own button plates, bar frame and spacing. Native clicks, tooltips and notifications stay intact.", "Blizzard aporta los iconos. La Suite conserva sus propias placas de botón, el marco de la barra y el espaciado. Los clics, las descripciones emergentes y las notificaciones originales siguen intactos.")
T("Blizzard supplies the name and health values. Mapko requests full enemy plates and both health values so normal enemies show text too. Width and height change only the enemy health bar in pixels; 0 keeps the selected bar dimensions. Backdrop, border and role fill are separate live skin layers in the preview; right-click a layer for its setting. Role colors use the saved palette; mana is only a caster hint. Open the three-dot menu here or Nameplates in MSUF Colors to change the palette.", "Blizzard proporciona el nombre y los valores de salud. Mapko solicita placas enemigas completas y ambos valores de salud para que los enemigos normales también muestren texto. Anchura y altura solo cambian la barra de salud enemiga en píxeles; 0 conserva las dimensiones elegidas. Fondo, borde y relleno por función son capas independientes en la vista previa; haz clic derecho en una capa para abrir su ajuste. Los colores por función usan la paleta guardada; el maná solo indica posibles lanzadores de hechizos. Abre aquí el menú de tres puntos o Placas de nombre en Colores de MSUF para cambiar la paleta.")
T("Blizzard symbols", "Símbolos de Blizzard")
T("Blizzard window controls", "Controles de ventana de Blizzard")
T("Blizzard windows", "Ventanas de Blizzard")
T("Blizzard yellow and chat system text", "Amarillo de Blizzard y texto del sistema en el chat")
T("Blizzard's Cooldown Manager stops completely. While your MSUF frames follow its bars, MSUF keeps it running invisibly.", "El gestor de reutilización de Blizzard se detiene por completo. Mientras tus marcos de MSUF sigan sus barras, MSUF lo mantiene funcionando de forma invisible.")
T("Blizzard's bars keep running, invisible, so frames that other addons attach to them stay in place.", "Las barras de Blizzard siguen funcionando, invisibles, para que los marcos que otros addons acoplan a ellas se queden en su lugar.")
