T("Blizzard's own buttons stay functional. The row is their starting position; drag each icon freely in the preview.", "Los botones propios de Blizzard siguen funcionando. La fila es su posición inicial; arrastra cada icono libremente en la vista previa.")
T("Blizzard's own cooldown swipe fills the ring: the global cooldown after each ability, and casts or channels while they run. A cast takes the place of the global cooldown until it ends; the bright edge marks how far the cast has come.", "La animación de reutilización propia de Blizzard llena el anillo: el tiempo de reutilización global tras cada habilidad y los lanzamientos o canalizaciones mientras duran. Un lanzamiento ocupa el lugar del tiempo de reutilización global hasta que termina; el borde brillante marca cuánto ha avanzado.")
