T("Bubbles outside instances can take the MSUF look; Blizzard locks the ones inside instances. Each source keeps Blizzard's look or uses the MSUF one: the shared look or its own font, size, colors, spacing and width. A bubble is matched to the line it shows right after that line arrives. Turning bubbles off inside instances uses Blizzard's bubble settings and gives them back when you leave or turn it off.", "Los bocadillos fuera de instancias pueden usar el aspecto de MSUF; Blizzard bloquea los de dentro de las instancias. Cada origen conserva el aspecto de Blizzard o usa el de MSUF: el aspecto común o su propia fuente, tamaño, colores, márgenes y anchura. Un bocadillo se asocia a la línea que muestra justo después de que llega esa línea. Desactivar los bocadillos dentro de instancias usa los ajustes de bocadillos de Blizzard y los regresa al salir o al desactivarlo.")
