T("Choose %s for \"%s\".", "Elige %s para «%s».")
T("Choose Clean Modern, Midnight Blue, MSUF Forever Glass, Midnight Dark or Class Style for Skinning and enabled Suite modules. Modules enabled later inherit it.", "Elige Limpio y moderno, Midnight Blue, Vidrio MSUF Forever, Midnight Dark o Estilo de clase para los skins y los módulos activos de la Suite. Los módulos que actives después lo heredan.")
T("Choose Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever or Class Style. This changes only the bag window colors and opacity; item slots and Blizzard bag actions remain intact.", "Elige Limpio y moderno, Midnight Blue, Midnight Dark, MSUF Forever o Estilo de clase. Solo cambia los colores y la opacidad de las bolsas; las casillas y acciones de Blizzard se mantienen intactas.")
T("Choose Clean Modern, Midnight Blue, neutral Midnight Dark glass or MSUF Forever's dark gold frame. All use MSUF's bar texture and font. Turn the 20 XP divisions on or off. The lower line can show session gain, XP per hour and time to level. Move or resize the bar in MSUF Edit Mode; its popup edits X, Y, width, height and scale. Hover for exact values. A session survives /reload and starts fresh on the next login.", "Elige Clean Modern, Midnight Blue, el cristal neutro Midnight Dark o el marco dorado oscuro de MSUF Forever. Todos usan la textura de barra y la fuente de MSUF. Activa o desactiva las 20 divisiones de EXP. La línea inferior puede mostrar la EXP ganada en esta sesión, la EXP por hora y el tiempo hasta el próximo nivel. Mueve o cambia el tamaño de la barra en el modo de edición de MSUF; su ventana emergente permite ajustar X, Y, anchura, altura y escala. Pasa el cursor para ver las cifras exactas. La sesión se conserva tras /reload y empieza de nuevo al iniciar sesión.")
T("Choose Clean Modern, classic MSUF or the complete Forever factory.", "Elige Limpio y moderno, MSUF clásico o la configuración completa de Forever.")
T("Choose Custom layout to set the order of total, per-second and percent values, then pick spaces, brackets or a separator. The percent switch controls main rows; breakdown rows show available shares. Unavailable shares are omitted. Primary means per second for DPS/HPS and total for other meters. Text settings also apply to headers, details and the floating timer. Slug uses WoW's crisp font renderer with an outline and no shadow. Protected values show without a percentage until combat ends.", "Elige Diseño personalizado para definir el orden de los valores total, por segundo y porcentaje; luego elige espacios, corchetes o un separador. El interruptor de porcentaje controla las filas principales; las filas de desglose muestran las proporciones disponibles. Las proporciones no disponibles se omiten. Principal significa por segundo para DPS/HPS y total para los demás medidores. Los ajustes de texto también se aplican a los encabezados, los detalles y el temporizador flotante. Slug usa el renderizador de fuentes nítido de WoW con contorno y sin sombra. Los valores protegidos se muestran sin porcentaje hasta que termina el combate.")
T("Choose Suite modules", "Elige los módulos de la Suite")
T("Choose a bar to adjust its layout below. The preview uses sample buttons; empty slots and stances can differ in game.", "Elige una barra para ajustar su diseño abajo. La vista previa usa botones de ejemplo; las casillas vacías y las actitudes pueden variar en el juego.")
T("Choose a font", "Elige una fuente")
T("Choose a line, then press Ctrl+C", "Elige una línea y luego presiona Ctrl+C")
T("Choose a look", "Elige un aspecto")
T("Choose a look and when the Suite bar appears. Visibility rules use the Suite layout; Blizzard layout keeps Blizzard's visibility. MSUF Edit Mode reveals the bar for moving.", "Elige un aspecto y cuándo aparece la barra de la Suite. Las reglas de visibilidad usan el diseño de la Suite; el diseño de Blizzard mantiene la visibilidad de Blizzard. El modo de edición de MSUF muestra la barra para moverla.")
T("Choose a look below; this sample follows your changes.", "Elige un aspecto abajo; esta muestra sigue tus cambios.")
T("Choose a look, then adjust its colors.", "Elige un estilo y ajusta sus colores.")
T("Choose a preset below or fine-tune with the slider.", "Elige un preajuste abajo o ajústalo con precisión con el control deslizante.")
T("Choose a profile that exists in both parts of the suite", "Elige un perfil que exista en ambas partes de la Suite")
T("Choose a random owned Hearthstone variant for the next click", "Elegir una variante de piedra de hogar poseída al azar para el siguiente clic")
T("Choose a smaller stack size and make sure the item is unlocked, your cursor is empty and you are out of combat.", "Elige un montón más pequeño y comprueba que el objeto no esté bloqueado, el cursor esté vacío y estés fuera de combate.")
T("Choose a sound", "Elige un sonido")
T("Choose a style above or change these colors to make a Custom look. Rows update immediately.", "Elija un estilo arriba o cambie estos colores para crear una apariencia personalizada. Las filas se actualizan inmediatamente.")
T("Choose a style, font and coverage in minutes. Every deeper control remains available in Expert mode.", "Elige estilo, fuente y cobertura en minutos. Todos los controles avanzados siguen disponibles en el modo Experto.")
T("Choose a template", "Elige una plantilla")
T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "Elige una fuente de MSUF, contorno, sombra y renderizado Suave, Nítido o Slug. Slug no tiene sombra. Los colores de etiqueta, valor y advertencia son independientes.")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "Elige una fuente y una textura de barra de MSUF o SharedMedia. El tamaño de fuente, el contorno, la sombra, el renderizado Suave/Nítido/Slug, la altura de barra y el espaciado actualizan el HUD al instante. Slug no tiene sombra.")
T("Choose broad UI families. Dedicated secure behavior and semantic artwork remain untouched.", "Elige grandes familias de la interfaz. El comportamiento protegido específico y los gráficos con significado no se tocan.")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "Elige nombres de broker e ID de monedas descubiertas por posición. Selecciona tus monedas de blasones de la temporada actual en la lista nativa; las selecciones guardadas funcionan al iniciar sesión sin visitar a un PNJ de mejoras. El orden de selección y el separador controlan el bloque de blasones. Los niveles de mejora observados siguen disponibles como alternativa tras seleccionar un objeto mejorable durante esta sesión. Las acciones de piedra de hogar requieren un clic deliberado.")
T("Choose buffs and consumables to track.", "Elige los beneficios y consumibles que quieres seguir.")
T("Choose clean window controls and a complete Micro Bar style, then tune individual artwork only when needed.", "Elige controles de ventana limpios y un estilo completo para el micromenú; ajusta gráficos específicos solo si es necesario.")
T("Choose coverage", "Elige la cobertura")
T("Choose crest currencies", "Elegir monedas de blasones")
T("Choose currencies", "Elegir monedas")
T("Choose data for place %d", "Elige datos para el lugar %d")
T("Choose each Blizzard popup separately. The feature hides its window when it appears and leaves the underlying game events intact. Combat lockdown can prevent hiding a protected window.", "Elija cada ventana emergente de Blizzard por separado. La función oculta su ventana cuando aparece y deja intactos los eventos subyacentes del juego. El bloqueo de combate puede evitar que se oculte una ventana protegida.")
T("Choose individual recurring UI errors to hide with Blizzard's own message filter.", "Elija errores de interfaz de usuario recurrentes individuales para ocultarlos con el filtro de mensajes propio de Blizzard.")
T("Choose observed seasonal stages", "Elegir niveles de temporada observados")
T("Choose one font for Blizzard UI text. Existing sizes, outlines, shadows and accessibility scaling are preserved.", "Elige una fuente para el texto de la interfaz de Blizzard. Se conservan los tamaños, contornos, sombras y el escalado de accesibilidad existentes.")
T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "Elige la vista detallada del personaje y su información adicional. Cambiar la vista recarga la interfaz.")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "Elige las dificultades de calabozo en las que MSUF inicia el registro de combate. Mítica+ comienza cuando se activa la piedra angular.")
T("Choose the information shown in each bar.", "Elige la información que aparece en cada barra.")
T("Choose the map shape, then adjust its border and outer shadow.", "Elige la forma del mapa y luego ajusta su borde y su sombra exterior.")
T("Choose the raid difficulties where MSUF starts the combat log.", "Elige las dificultades de banda en las que MSUF inicia el registro de combate.")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "Elige los colores y el marco compartidos de los botones. El diseño, las asignaciones de teclas y la visibilidad se mantienen como están. Cambiar un color individual cambia la etiqueta a Personalizado.")
T("Choose the values shown on each bar.", "Elige los valores que aparecen en cada barra.")
T("Choose what the Suite tracker lists and when it steps aside.", "Elige qué muestra el rastreador de la Suite y cuándo se hace a un lado.")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "Elige dónde aparecen las acciones recientes. Las profundidades tienen su propio interruptor; los campos de batalla y las arenas comparten uno, y los demás escenarios siguen a «Fuera de estancias». Donde el registro está desactivado, no escucha tus lanzamientos.")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "Elige qué interfaces de Blizzard reciben el skin. Blizzard conserva sus interacciones.")
T("Choose your bars", "Elige tus barras")
T("Choose your profile", "Elige tu perfil")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "Elegir un aspecto actualiza Skins y todos los módulos activos de la Suite. Los módulos que actives después lo heredan. Los nuevos perfiles de skin empiezan con %s.")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "La confirmación se puede omitir después de que elijas salir. La omisión automática es una opción independiente e incluye los videos. Ambas se desactivan en combate, y una secuencia de vehículo siempre conserva su confirmación de salida. Este asistente puede ocultar los tutoriales, rellenar la palabra de borrado manteniendo manual la confirmación final, ocultar solo el aviso de captura realizada o abrir tu ventana de personaje en los vendedores, en la última pestaña que usaste. En la casa de subastas, el botón de filtros de Blizzard se marca mientras «Solo expansión actual» esté desactivado; márcalo ahí una vez y Blizzard lo guarda para este personaje.")
T("Cinematic zone and event announcements in the Suite look.", "Anuncios cinemáticos de zonas y eventos con el aspecto de la Suite.")
