T("Clean Modern is the Retail default; MSUF Forever is the Forever default. Midnight Blue keeps the original blue glass. Open a section's three-dot menu to change its colors, or use MSUF Colors for the full palette. Your own color changes become Custom.", "Limpio y moderno es el estilo predeterminado de Retail; MSUF Forever es el de Forever. Midnight Blue conserva el cristal azul original. Abre el menú de tres puntos de una sección para cambiar sus colores o usa Colores de MSUF para toda la paleta. Tus cambios de color pasan a ser Personalizado.")
T("Clean Modern uses matte panels with white accents. Midnight Blue keeps the original blue palette. Midnight Dark uses neutral charcoal glass; MSUF Forever retains its muted gold. Color changes become Custom.", "Limpio y moderno usa paneles mates con detalles blancos. Midnight Blue conserva la paleta azul original. Midnight Dark usa cristal gris carbón neutro; MSUF Forever mantiene su dorado suave. Los cambios de color pasan a ser Personalizado.")
T("Clean Modern · Suite and Skin, MSUF frames retained", "Limpio y moderno · Suite y Skin, marcos de MSUF conservados")
T("Clean Modern, Midnight Blue, Midnight Dark and MSUF Forever are complete looks in Style. Color palettes here change colors only; use Expert mode for every UI state.", "Limpio y moderno, Midnight Blue, Midnight Dark y MSUF Forever son aspectos completos en Estilo. Aquí las paletas de color solo cambian los colores; usa el modo Experto para cada estado de la interfaz.")
T("Clean Studio", "Estudio limpio")
T("Clean profile created", "Perfil vacío creado")
T("Clear", "Borrar")
T("Clear new mount markers", "Borrar nuevos marcadores de montura")
T("Clear new mount, pet and toy fanfares acquired while this helper is active.", "Quita las marcas de novedad de monturas, mascotas y juguetes obtenidos mientras este asistente está activo.")
T("Clear new pet markers", "Quitar marcas de novedad de mascotas")
T("Clear new toy markers", "Quitar marcas de novedad de juguetes")
T("Clear only new mount, pet and toy fanfares acquired while this helper is active. Your collection entries remain available. Each collection type can be switched off independently.", "Quita solo las marcas de novedad de monturas, mascotas y juguetes obtenidos mientras este asistente está activo. Los elementos siguen en tu colección. Puedes desactivar cada tipo de colección por separado.")
T("Clear previous mark", "Borrar marca anterior")
T("Clear recent items", "Borrar objetos recientes")
T("Clear run history", "Borrar historial de partidas")
T("Clear saved character gold", "Borrar los datos de oro guardados de los personajes")
T("Clear saved chat history", "Borrar historial de chat guardado")
T("Clear saved selection", "Borrar selección guardada")
T("Clear selection", "Borrar selección")
T("Clear the saved chat history of this character in every chat window? This cannot be undone.", "¿Borrar el historial de chat guardado de este personaje en todas las ventanas de chat? No se puede deshacer.")
T("Clear the saved gold balances of all your characters and their gold history? This cannot be undone.", "¿Borrar el oro guardado de todos tus personajes y su historial de oro? No se puede deshacer.")
T("Clear worldmarks", "Borrar marcadores del mundo")
T("Click a bar to open the spell breakdown in the window; hover it for a short tooltip.", "Haz clic en una barra para abrir el desglose de hechizos en la ventana; pasa el cursor sobre ella para ver una descripción breve.")
T("Click a place to choose its text. Drag the bar in MSUF Edit Mode. Empty places disappear. The Antique Footer preset creates a bag, durability and clock strip on this bar only.", "Haz clic en un lugar para elegir su texto. Arrastra la barra en el modo de edición de MSUF. Los lugares vacíos desaparecen. El preajuste Pie antiguo crea una franja con bolsas, durabilidad y reloj solo en esta barra.")
T("Click a reminder to cast its spell or use its item. Aura checks run on relevant events; there is no repeating scan.", "Haz clic en un recordatorio para lanzar su hechizo o usar su objeto. Las comprobaciones de auras se ejecutan con los eventos relevantes; no hay escaneo repetitivo.")
T("Click a spell for its settings", "Haz clic en un hechizo para ver sus ajustes")
T("Click again to delete", "Haz clic otra vez para borrar")
T("Click for bag options", "Clic para opciones de bolsas")
T("Click opens the world map", "Clic abre el mapa del mundo")
T("Click the minimap button for Blizzard's specialization and loot specialization choices. Choices are disabled in combat and the button hides when both menus are turned off.", "Haz clic en el botón del minimapa para elegir la especialización o la especialización de botín mediante los menús de Blizzard. No se pueden usar en combate y el botón se oculta si ambos menús están desactivados.")
T("Click to edit this bar, right-click for its actions. Drop a spell here to move it to this bar.", "Haz clic para editar esta barra; clic derecho para sus acciones. Suelta un hechizo aquí para moverlo a esta barra.")
T("Click to open its Basics: size and attachment.", "Haz clic para abrir sus Básicos: tamaño y acople.")
T("Click to open the death recap.", "Clic para abrir el resumen de muerte.")
T("Click to open the full gold history.", "Haz clic para abrir el historial de oro completo.")
T("Click to open the world map.", "Clic para abrir el mapa del mundo.")
T("Click to open your equipment.", "Clic para abrir tu equipo.")
T("Click to preview; right-click for settings", "Clic para vista previa; clic derecho para ajustes")
T("Click to select; drag or use arrow keys; edit exact X/Y below.", "Haz clic para seleccionar; arrastra o usa las flechas; edita X/Y exactos abajo.")
T("Click to show or hide the collected buttons.", "Haz clic para mostrar u ocultar los botones reunidos.")
T("Click to stop after the current purchase.", "Haga clic para detener después de la compra actual.")
T("Click: change live setting; right-click: settings", "Clic: cambiar ajuste en vivo; clic derecho: ajustes")
T("Click: settings", "Clic: ajustes")
