T("Double-click a search result to open Blizzard's application dialog. With submit on double-click, the second click also signs up with the roles already chosen in that dialog; hold Shift to review it instead. A saved note can appear beside the dialog for copying; it is stored when you finish editing.", "Haz doble clic en un resultado de búsqueda para abrir la ventana de solicitud de Blizzard. Con el envío por doble clic, el segundo clic también te inscribe con los roles ya elegidos en esa ventana; mantén presionado Mayús para revisarla en su lugar. Una nota guardada puede aparecer junto a la ventana para copiarla; se guarda al terminar de editarla.")
