T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "Arrastra una ventana por su borde superior; arrastra la esquina inferior derecha para escalarla. El botón de menos de la esquina superior derecha contrae las ventanas compatibles a una pestaña de restauración. Las bolsas y las ventanas protegidas mantienen su comportamiento nativo.")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "Arrastra los anuncios en el modo de edición de MSUF o define aquí su duración, escala y posición exacta.")
