T("Drag the bag title to move it; click for options.", "Arrastra el título de la bolsa para moverla; pulsa para ver opciones.")
T("Drag the bar's edge to move it on screen.", "Arrastra el borde de la barra para moverla en la pantalla.")
T("Drag the reagent bag title while it is open to move it independently. Click the title for bag options. Reset its position in MSUF Edit Mode to follow Blizzard's normal bag layout again.", "Arrastra el título de la bolsa de componentes mientras está abierta para moverla por separado. Haz clic en el título para ver las opciones de bolsa. Restablece su posición en el modo de edición de MSUF para que vuelva a seguir el diseño normal de bolsas de Blizzard.")
T("Drag the result card in MSUF Edit Mode, or set its screen anchor, width, scale and position here.", "Arrastra la tarjeta de resultados en el modo Edición de MSUF o ajusta aquí su anclaje, ancho, escala y posición.")
T("Drag the title of an open bag to move it. Click the title for bag options. Each bag keeps its own position. Blizzard shows your current gold on the right; the optional Session value on the left shows the change since login and survives /reload. Adjust the combined bag size here or in its MSUF Edit Mode popup. Reset position in Edit Mode returns the window to Blizzard's normal anchor.", "Arrastra el título de una bolsa abierta para moverla. Haz clic en el título para ver las opciones de bolsa. Cada bolsa mantiene su propia posición. Blizzard muestra tu oro actual a la derecha; el valor opcional Sesión a la izquierda muestra el cambio desde el inicio de sesión y sobrevive a /reload. Ajusta aquí el tamaño de las bolsas combinadas o en su ventana emergente del modo de edición de MSUF. Restablecer posición en el modo de edición devuelve la ventana al ancla normal de Blizzard.")
