T("For Warlocks: show Burning Rush only while its aura is active in combat. Blizzard's native aura container follows the aura; Suite does not scan auras. MSUF Edit Mode shows a sample and moves the cue.", "Para brujos: muestra Ímpetu ardiente solo mientras su aura esté activa en combate. El contenedor de auras original de Blizzard sigue el aura; Suite no analiza las auras. El modo de edición de MSUF muestra una vista previa y mueve el aviso.")
