T("Forever only. Route times are learned from completed flight-master journeys and kept in this profile. A first journey has no invented estimate. Early landing does not overwrite a full-route time. Intermediate stops come from the native taxi map; its tooltip can preview the route. Land at next stop requests the next available landing point.", "Solo Forever. Aprende tiempos de viajes completos y los guarda en este perfil. El primer viaje no tiene una estimación inventada. Aterrizar antes no sobrescribe el tiempo completo. Las paradas proceden del mapa nativo de vuelo, cuya ayuda puede mostrar la ruta. «Aterrizar en la siguiente parada» solicita el siguiente punto disponible.")
