T("Hide Blizzard's main tooltip in combat, in instances, or for selected item, spell and unit tooltips. MSUF unit and group frame tooltips keep their own visibility settings; aura tooltips keep their Show Tooltip switches. Each choice works independently. A hidden tooltip turns fully transparent, so Blizzard keeps handling it as usual.", "Oculta la descripción emergente principal de Blizzard en combate, en instancias o para objetos, hechizos y unidades seleccionados. Las descripciones de los marcos de unidad y grupo de MSUF conservan sus propios ajustes de visibilidad; las de auras conservan sus opciones Mostrar descripción emergente. Cada opción funciona por separado. Una descripción oculta se vuelve totalmente transparente, así Blizzard la sigue gestionando como siempre.")
