T("Hide the Suite Micro Bar when any selected condition is true. The health condition uses your character's health; at full health the transparent bar can still receive clicks. MSUF Edit Mode shows the bar for placement. Blizzard layout keeps Blizzard's visibility.", "Oculta el micromenú de la Suite cuando se cumple cualquier condición seleccionada. La condición de salud usa la salud de tu personaje; con la salud completa, la barra transparente aún puede recibir clics. El modo de edición de MSUF muestra la barra para ubicarla. El diseño de Blizzard mantiene la visibilidad de Blizzard.")
