T("How the icons line up and grow. A free bar's position counts from the screen center; an attached bar's is an offset from its attach point. Excess cooldowns can move past Maximum icons to another enabled cooldown bar. The destination must have overflow off; chained routes are ignored.", "Alineación y crecimiento de los iconos. La posición de una barra libre parte del centro de la pantalla; la de una barra anclada es relativa a su anclaje. Los tiempos de reutilización que superen Máximo de iconos pueden pasar a otra barra activa. El destino debe tener el desbordamiento desactivado; las rutas encadenadas se ignoran.")
