T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "Conserva la cuadrícula de Blizzard o elige una cuadrícula de la Suite, grupos por bolsa física o categorías. Usa Editar categorías en la ventana de bolsas para crear, renombrar, ordenar o desactivar categorías; arrastra objetos a una categoría lateral para asignarlos. Desplázate o usa Anterior y Siguiente para inventarios grandes; en combate se muestran todas las casillas a la vez. Los recuentos combinados son solo visuales; los montones físicos siempre se restauran en el banco, el banco de hermandad, el correo, el comercio, la subasta y el mercader.")
