T("MSUF icons replace the scattered Blizzard chat controls. Friends, channels, text to speech and the chat menu keep their Blizzard actions; the bottom icon jumps to the newest message. Turn this off to restore the native buttons.", "Los iconos de MSUF reemplazan los controles dispersos del chat de Blizzard. Amigos, canales, texto a voz y el menú del chat conservan sus acciones de Blizzard; el icono inferior salta al mensaje más reciente. Desactiva esto para restaurar los botones nativos.")
