T("MSUF looks use Suite glyphs and a player portrait. Blizzard keeps every button action and tooltip.", "Los aspectos de MSUF usan glifos de la Suite y un retrato del jugador. Blizzard conserva todas las acciones y descripciones emergentes de los botones.")
