T("Mainline covers Rogue poisons, this season's flasks, augment runes and weapon oils, and the Well Fed food buff. Each category clicks the first matching item in your bags; an item you enter for it is tried first. Food is found in your bags by the game's eating spells: the food you enter comes first, then the newest one. With the gray reminder on, a category with nothing left stays visible without a click action. Assassination prefers Deadly Poison; Outlaw and Subtlety prefer Instant Poison. Dragon-Tempered Blades allows two poisons per category. Oils target equipped weapons; known Shaman or Paladin imbues suppress automatic oils.", "Mainline cubre los venenos de pícaro, los frascos, runas de aumento y aceites de arma de esta temporada, y el beneficio de comida Bien alimentado. Cada categoría usa al hacer clic el primer objeto adecuado de tus bolsas; un objeto que indiques para ella se prueba primero. La comida se busca en tus bolsas por los hechizos de comer del juego: primero la que indiques y luego la más reciente. Con el recordatorio gris, una categoría agotada sigue visible sin acción de clic. Asesinato prefiere Veneno mortal; Forajido y Sutileza prefieren Veneno instantáneo. Hojas templadas por dragones permite dos venenos por categoría. Los aceites apuntan a armas equipadas; los encantamientos conocidos de chamán o paladín suprimen los aceites automáticos.")
