T("One combined bag with a clear Suite background and item levels on equipment. Keep Blizzard's own item grid, or choose a Suite view with pages, bag groups or categories. Using and sorting items stays Blizzard's.", "Una bolsa combinada con un fondo claro de la Suite y niveles de objeto sobre el equipo. Conserva la cuadrícula de objetos propia de Blizzard o elige una vista de la Suite con páginas, grupos por bolsa o categorías. Usar y ordenar objetos sigue a cargo de Blizzard.")
