T("Only containers newly acquired after enabling this helper are opened. It waits for combat to end, opens one at a time, and leaves them to you while you hold Shift or a loot window or a window that gives item use another meaning is open: merchant, bank, guild bank, mail, trade, auction house, scrapper, socket, upgrade and similar. Warbound containers stay unopened unless you allow them; profiles that used this helper before keep opening them. Midnight Artisan payouts can wait while your Shard of Dundun is capped.", "Solo se abren los contenedores obtenidos después de activar este asistente. Espera a que termine el combate, abre uno cada vez y te los deja si mantienes Mayús o hay abierta una ventana de botín o una ventana que da otro sentido a usar un objeto: vendedor, banco, banco de hermandad, correo, intercambio, casa de subastas, desguazadora, engarce, mejora y similares. Los contenedores de banda guerrera siguen cerrados salvo que los permitas; los perfiles que ya usaban este asistente los siguen abriendo. Los pagos de artesano de Midnight pueden esperar mientras tus Fragmentos de Dundun estén en el límite.")
T("Only in an active Delve and outside combat: if the player choice has exactly one enabled spell option, one button and no confirmation, MSUF selects it once. Other choices remain manual.", "Solo en un Abismo activo y fuera de combate: si la elección del jugador tiene exactamente una opción de hechizo habilitada, un botón y ninguna confirmación, MSUF la selecciona una vez. Las demás elecciones siguen siendo manuales.")
