T("Optional Blizzard settings for chat, map, sound and low-health or alternate screen flashes. MSUF restores the previous value when you turn a choice or this helper off. Changes you make yourself in Blizzard settings while this helper runs are respected.", "Ajustes opcionales de Blizzard para el chat, el mapa, el sonido y los destellos de pantalla por salud baja o alternativos. MSUF restaura el valor anterior al desactivar una opción o el asistente. Los cambios que hagas por tu cuenta en los ajustes de Blizzard mientras funciona el asistente se respetan.")
