T("Priority: focus, safe tank aggro, threat, tapped, quest, neutral, then NPC type. Turning focus off allows the next rule. Disabled threat overrides preserve Blizzard's active threat color. Tank mode uses your effective role; warnings also work for damage/healers. Secret values stay with Blizzard.", "Prioridad: foco, aggro seguro de tanque, amenaza, reclamado, misión, neutral y luego tipo de PNJ. Desactivar el foco permite la siguiente regla. Las anulaciones de amenaza desactivadas conservan el color de amenaza activo de Blizzard. El modo tanque usa tu rol efectivo; las advertencias también funcionan para daño/sanadores. Los valores secretos se quedan con Blizzard.")
