T("Selected currencies appear above the bag footer. Click Gold history for recorded character balances and 30 days of this character's income and spending, by local date. Other characters show their last recorded balance. The history starts when enabled and does not reconstruct earlier transactions; Clear saved character gold removes the history and the balances.", "Las monedas elegidas aparecen sobre el pie de la ventana de bolsas. Haz clic en Historial de oro para ver los saldos registrados de personajes y 30 días de ingresos y gastos de este personaje, por fecha local. Los demás personajes muestran su último saldo registrado. El historial empieza al activarlo y no reconstruye transacciones anteriores; Borrar los datos de oro guardados de los personajes elimina el historial y los saldos.")
