T("Selected profession outfits and cosmetic auras are removed outside combat. Fishing is excluded. Noggenfogger skeleton removal also removes its underwater-breathing effect. Client refusal stops this helper until settings change.", "Los atuendos de profesión y las auras cosméticas seleccionados se eliminan fuera de combate. Se excluye Pesca. Al quitar el esqueleto de Tragonublo también se elimina su respiración bajo el agua. Si el cliente lo impide, la función se detiene hasta que cambies sus ajustes.")
