T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "Alterna entre pestañas nativas, banco combinado, banco de banda guerrera combinado y categorías compartidas con el botón bajo la ventana del banco. Las categorías compartidas incluyen pestañas accesibles del personaje y de la banda guerrera. Gestionar pestañas del banco vuelve a las compras, depósitos y ajustes de Blizzard. Cada casilla conserva su propia acción y los montones del banco nunca se combinan; al hacer clic en un objeto de la banda guerrera se selecciona primero la pestaña Banco de banda guerrera de Blizzard, y un objeto reembolsable pregunta antes de entrar al banco de banda guerrera.")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Open Customize a bar below for layout and other options.", "Activa o desactiva cada barra aquí. Al volver a activarla se restaura su modo de visibilidad anterior. Abre Personalizar una barra abajo para el diseño y otras opciones.")
