T("Tick every demon you want out; demons your character has not learned yet can be ticked too. A summoned demon you left unticked gets a notice, as long as one of your ticked demons can be summoned. Another look of a demon counts as that demon once you have summoned it in that look.", "Marca cada demonio que quieras tener fuera; también puedes marcar demonios que tu personaje aún no ha aprendido. Un demonio invocado sin marcar recibe un aviso, siempre que uno de tus demonios marcados se pueda invocar. Otro aspecto de un demonio cuenta como ese demonio en cuanto lo hayas invocado con ese aspecto.")
