T("Timestamps use Blizzard's chat setting across all chat windows. Copy is off by default; when enabled, move its button with X/Y, choose a message, then press Ctrl+C. The displayed timestamp is included when timestamps are on. The message tools leave the Combat Log alone (its own settings can add a timestamp to every line); its lines still wake the idle fade. Saved history belongs to this character.", "Las marcas de tiempo usan el ajuste de chat de Blizzard en todas las ventanas de chat. Copiar está desactivado por defecto; al activarlo, mueve su botón con X/Y, elige un mensaje y presiona Ctrl+C. La marca de tiempo mostrada se incluye cuando las marcas de tiempo están activadas. Las herramientas de mensajes no tocan el registro de combate (sus propios ajustes pueden agregar una marca de tiempo a cada línea); sus líneas sí despiertan el desvanecido por inactividad. El historial guardado pertenece a este personaje.")
