T("Uses Blizzard's Sell All Junk action when a merchant opens, including its per-bag exclusions. Hold Shift while opening the merchant to skip selling. The optional chat line confirms the request, not completed sales.", "Usa la acción Vender toda la basura de Blizzard al abrir un comerciante, incluidas sus exclusiones por bolsa. Mantén Mayús al abrir el comerciante para omitir la venta. La línea opcional en el chat confirma la solicitud, no las ventas completadas.")
