T("Warn when your pet is missing or dead. By default, the missing warning applies to Hunters and Warlocks; the dead warning applies to any class with a pet. MSUF Edit Mode moves the alert.", "Avisa si falta tu mascota o ha muerto. De forma predeterminada, la alerta por ausencia se aplica a cazadores y brujos; la de muerte, a cualquier clase con mascota. Mueve el aviso en el modo de edición de MSUF.")
