T("When a dungeon queue pops", "Cuando aparece una cola de calabozo")
T("When a ready check starts outside combat and your mana as a healer is low, a short note shows how much you have; it turns red below half of your limit. Only your own mana is read.", "Cuando empieza una verificación de listos fuera de combate y tu maná de sanador es bajo, una nota breve muestra cuánto tienes; se vuelve roja por debajo de la mitad de tu límite. Solo se lee tu propio maná.")
T("When leaving", "Al salir")
T("When someone offers you a resurrection, its dialog gets a green frame, optionally with Blizzard's ready check sound, and its accept button can get a green frame of its own. Accepting stays your click.", "Cuando alguien te ofrece una resurrección, su diálogo recibe un marco verde, opcionalmente con el sonido de verificación de listos de Blizzard, y su botón de aceptar puede tener su propio marco verde. Aceptar sigue siendo tu clic.")
T("When the key ends", "Al terminar la piedra")
T("When the native group listing panel closes with applications still active, show their count in your own chat. Your applications remain active and no group chat is sent.", "Al cerrar la ventana de búsqueda de grupo con solicitudes aún activas, muestra su cantidad en tu chat local. Tus solicitudes permanecen activas y no se envía ningún mensaje al grupo.")
T("When the selected bar appears", "Cuándo aparece la barra seleccionada")
T("When this bar shows, and how far it fades out of combat. Tooltips show a spell when you hover its icon. This page and MSUF Edit Mode always show every bar.", "Cuándo se muestra esta barra y cuánto se desvanece fuera de combate. Las descripciones emergentes muestran un hechizo cuando pasas el cursor sobre su icono. Esta página y el modo de edición de MSUF siempre muestran todas las barras.")
T("When to remind", "Cuándo recordar")
T("When to show", "Cuándo mostrar")
T("Where are the Suite minimap settings?", "¿Dónde están los ajustes del minimapa de Suite?")
T("Where are the nameplate settings?", "¿Dónde están los ajustes de las placas de nombre?")
T("Where is the cooldown manager?", "¿Dónde está el gestor de tiempos de reutilización?")
T("Where the buff or debuff is looked for. Automatic: harmful spells on your target, all others on you.", "Dónde se busca el beneficio o perjuicio. Automático: hechizos dañinos en tu objetivo, todos los demás en ti.")
T("Where to show recent actions", "Dónde mostrar acciones recientes")
T("Which number is drawn on top when both show.", "Qué número se dibuja encima cuando se muestran ambos.")
T("Which numbers show, which one is drawn on top, and their size and place. Single spells can differ: click them in the preview. The font settings below apply to every bar; Slug has no shadow.", "Qué números se muestran, cuál se dibuja encima, y su tamaño y lugar. Los hechizos individuales pueden variar: haz clic en ellos en la vista previa. Los ajustes de fuente de abajo se aplican a todas las barras; Slug no tiene sombra.")
T("While DataTexts and this choice are enabled, MSUF remembers this character's gold at login and after money changes. Hover a Gold or Session gold DataText to see the last known account total and up to eight other characters. No background scans are used.", "Mientras los textos de datos y esta opción estén activos, MSUF guarda el oro del personaje al iniciar sesión y cuando cambia. Pasa el cursor sobre un texto de Oro u Oro de sesión para ver el último total conocido de la cuenta y hasta ocho personajes más. No se realizan exploraciones en segundo plano.")
T("While DataTexts is active, hide Blizzard's backpack and bag slots. A Bag space DataText opens the native bags when clicked. Turn this off to restore the Blizzard buttons.", "Mientras Textos de datos está activo, oculta la mochila y las casillas de bolsas de Blizzard. Un texto de datos Espacio en bolsas abre las bolsas nativas al hacer clic. Desactiva esto para restaurar los botones de Blizzard.")
T("While a key runs, each defeated boss shows how far ahead or behind you are: against the best time you ever had on that boss, or against the boss times of your fastest completed run, at this keystone level or at any. Only runs this character completed count. With target times on, bosses still alive show the time to beat.", "Mientras una piedra está en curso, cada jefe derrotado muestra cuánto vas por delante o por detrás: frente al mejor tiempo que hayas tenido con ese jefe o frente a los tiempos de jefe de tu recorrido completado más rápido, en este nivel de piedra o en cualquiera. Solo cuentan los recorridos que completó este personaje. Con los tiempos objetivo activados, los jefes que siguen vivos muestran el tiempo a superar.")
T("While the buff of this spell lasts, the icon shows its duration and stacks instead of the cooldown.", "Mientras dura el beneficio de este hechizo, el icono muestra su duración y acumulaciones en lugar de la reutilización.")
