T("Windows update from the client's own combat data: every event outside combat, and at the chosen interval during combat.", "Las ventanas se actualizan con los propios datos de combate del cliente: con cada evento fuera de combate y al intervalo elegido durante el combate.")
T("Wine-black panels with dusty rose controls.", "Paneles negro vino con controles rosa empolvado.")
T("WoW Forever only. Lists your group's threat on the watched enemy from Blizzard's threat data, highest first; for a friendly target, its enemy is used. Values the game keeps hidden are left out. Turn the mouse wheel over the window when more members are listed than rows fit. The red mark shows where you would take aggro, which is not the point where you match the tank. The meter repaints at most five times a second and reads no combat log.", "Solo WoW Forever. Muestra la amenaza de tu grupo sobre el enemigo vigilado con los datos de amenaza de Blizzard, de mayor a menor; con un objetivo amistoso se usa su enemigo. Los valores que el juego oculta se omiten. Gira la rueda del mouse sobre la ventana cuando haya más miembros que filas. La marca roja indica dónde atraerías la amenaza, que no es el punto en el que igualas al tanque. El medidor se redibuja como máximo cinco veces por segundo y no lee el registro de combate.")
